"        async function runQuickAction(cmd, payload) {
            // Clear any previous interval
            if (quickActionInterval) {
                clearInterval(quickActionInterval);
                quickActionInterval = null;
            }

            const resultPanel = document.getElementById('quick-start-result');
            const outputPre = document.getElementById('quick-start-output');

            if (resultPanel && outputPre) {
                resultPanel.classList.remove('hidden');
                outputPre.innerText = "Инициализация задачи...\n";

                let body = {};
                if (cmd === 'run_job') {
                    body = {
                        job: payload.job,
                        params: payload.params || {}
                    };
                } else {
                    body = payload;
                }

                // Hide evaluation results panel at start of action
                const evalResultPanel = document.getElementById('quick-start-eval-result');
                if (evalResultPanel) evalResultPanel.classList.add('hidden');

                try {
                    const res = await fetch(API_BASE + '/api/run_job', {
                        method: 'POST',
                        headers: {'Content-Type': 'application/json'},
                        body: JSON.stringify(body)
                    });

                    if (!res.ok) {
                        const errData = await res.json();
                        outputPre.innerText += `Ошибка запуска: ${errData.detail || 'Неизвестная ошибка'}\n`;
                        return;
                    }

